} from "@/lib/admin/auth-config";
import { getAdminEnvironment } from "@/lib/admin/environment";
import {
  getConfiguredAdminRole,
  getVerifiedGoogleAdminRole,
  hasConfiguredAdminUsers,
} from "@/lib/admin/rbac";

